using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {public sealed class StorageUITests {
 string dir;GameRuntime game;static void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
 [UnitySetUp]public IEnumerator Setup(){dir=Path.Combine(Path.GetTempPath(),"unity-storage-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
 [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
 [UnityTest]public IEnumerator ActualExportWebPreviewConfirmationRecoveryAndSevenLanguages(){Click("ResearchTab");yield return null;Click("StorageAccess");yield return null;Click("ExportUnitySave");Assert.That(Directory.GetFiles(Path.Combine(dir,"Exports")),Has.Length.EqualTo(1));string transfer=Path.Combine(dir,"web-transfer.json");File.Copy(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/WebImportReferenceCase.json"),transfer);GameObject.Find("RecoveryPathInput").GetComponent<InputField>().text=transfer;Click("InspectWebTransfer");Assert.That(game.State.Web.present,Is.False,"Preview must not replace the current state");Click("ConfirmRecovery");yield return null;Assert.That(game.State.Web.present,Is.True);Assert.That(Directory.GetFiles(Path.Combine(dir,"ImportOriginals"),"web-transfer-original-*"),Has.Length.EqualTo(1));var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);Assert.That(loaded.State.Web.original,Is.EqualTo(game.State.Web.original));Click("ExportBalanceHistory");Click("ExportLocalDiagnostics");foreach(string language in SettingsCatalog.Languages){game.Act(s=>SettingsRules.Change(s,"language",language));game.Show("story");yield return null;yield return null;var expected=NativeUiCatalog.Copies.First(c=>c.Values[1]=="Wie soll deine KI heißen?").Values[Array.IndexOf(SettingsCatalog.Languages,language)];Assert.That(GameObject.Find("StoryNamePrompt").GetComponent<Text>().text,Is.EqualTo(expected),language);foreach(int width in new[]{320,390,430})WorkshopTests.Capture(width,width==320?568:width==390?844:932,"/tmp/unity-story-"+language+"-"+width+".png");}game.Show("storage");yield return null;Click("ReadReturnReport");Assert.That(game.State.Return.read,Is.True);var credits=game.State.Credits;game.Show("storage");yield return null;Assert.That(game.State.Credits.CompareTo(credits),Is.Zero,"Displaying report grants nothing");}
}}
